from pathlib import Path
import json,html,hashlib
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'frontend/public/models/rsl';r=json.loads((OUT/'alphabet-report.json').read_text())
rows=''.join(f'<tr><td>{html.escape(c["label"])}</td><td>{c["correct"]} / {c["tested"]}</td><td>{100*c["correct"]/c["tested"]:.1f}%</td></tr>' for c in r['perClass'])
page=f'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Обучение ИИ: 33 буквы — AI Mentor</title><style>body{{font:17px/1.7 system-ui;background:#f7f3eb;color:#2e3540;max-width:900px;padding:30px;margin:auto}}table{{border-collapse:collapse;width:100%}}td,th{{padding:10px;text-align:left;border-bottom:1px solid #d4ccc0}}a{{color:#305c80}}strong{{font-size:1.1em}}</style><h1>33 буквы: что обучено и что проверено</h1><p>Самостоятельно обученный классификатор последовательности из 16 кадров. Готовая MediaPipe находит точки кистей, наш классификатор определяет букву. Внешний AI API не используется.</p><p>Обучение: <strong>{r['trainVideos']} видео, {r['trainSigners']} исполнителей</strong>. Тест: <strong>{r['testVideos']} видео, {r['testSigners']} других исполнителей</strong>. Пересечение людей: 0. {r["validationVideos"]} видео внутри обучающей части использовались для выбора регуляризации; тест не использовался для выбора модели.</p><p>Точность на всех тестовых видео: <strong>{r['accuracy']*100:.1f}%</strong>. Доля выданных ответов (без «нет жеста»): <strong>{r['acceptedCoverage']*100:.1f}%</strong>. Правильных среди выданных: <strong>{r['acceptedAccuracy']*100:.1f}%</strong>. Условия ответа: вероятность ≥ 0,70, отрыв от следующего класса ≥ 0,20, рука найдена минимум в 8 из 16 кадров. Отказы не считаются правильными ответами.</p><h2>Ограничения</h2><p>Это проверка на подмножестве Bukva, а не измерение точности на вашей камере. 33 изолированные буквы и класс no_event. Не обучены слова, непрерывная дактильная речь, грамматика, лицо и корпус. Неизвестные жесты могут ошибочно распознаваться как буквы. Ответ модели — подсказка, а не оценка владения РЖЯ.</p><h2>Проверка в браузере</h2><p>Дополнительно проверены три тестовых файла: Я распознана верно; видео без жеста получило отказ; Д ошибочно распознана как Я. Эти три проверки не являются отдельной оценкой точности. Личная веб-камера не проверялась. <a href="/models/rsl/browser-checks.json">Файлы и результаты проверки</a>.</p><h2>Ошибки видны по каждой букве</h2><table><thead><tr><th>Класс</th><th>Верно / проверено</th><th>Точность</th></tr></thead><tbody>{rows}</tbody></table><p><a href="/models/rsl/alphabet-report.json">Отчёт и матрица ошибок JSON</a> · <a href="https://github.com/ai-forever/bukva">Bukva, авторы и данные</a> · <a href="/research/rsl/bukva-license.pdf">Лицензия</a></p></html>'''
(ROOT/'frontend/public/research/rsl/alphabet-report.html').write_text(page)
p=ROOT/'ml/rsl/data/alphabet/manifest.json'
(OUT/'alphabet-provenance.json').write_text(json.dumps({'source':r['source'],'selection':'45 train and 18 test per class, SHA-256 ID order, official subject split','manifestSha256':hashlib.sha256(p.read_bytes()).hexdigest(),'features':'16 frames, 4 temporal bins of normalized dominant-hand coordinates, wrist movement, visibility, and 210 average pairwise distances','classifier':'multinomial logistic regression','validation':'signer-disjoint subset of train; C in [0.1,1,10]','pretrainedComponent':'MediaPipe Hand Landmarker (Google)','scripts':['ml/rsl/prepare_alphabet.py','ml/rsl/extract_alphabet.py','ml/rsl/train_alphabet.py']},indent=2))
